effect.shader:
void main() {
    // Em pixels da COMPOSIÇÃO: `acEscalaDePixel` converte para o buffer, e a prévia
    // reduzida (o Auto da tela, o play) fica do tamanho da exportação (0.516.0).
    vec2 offset = acTexelSize * (radius * acEscalaDePixel);
    vec4 center = texture(inputImg, acScreenNorm);

    // Média dos quatro vizinhos = uma versão borrada barata da imagem.
    vec3 blurred = (
        texture(inputImg, acScreenNorm + vec2( offset.x, 0.0)).rgb +
        texture(inputImg, acScreenNorm + vec2(-offset.x, 0.0)).rgb +
        texture(inputImg, acScreenNorm + vec2(0.0,  offset.y)).rgb +
        texture(inputImg, acScreenNorm + vec2(0.0, -offset.y)).rgb
    ) * 0.25;

    // "Unsharp mask": nitidez é a imagem MAIS a diferença entre ela e sua
    // versão borrada. Onde não há detalhe, a diferença é zero e nada muda —
    // por isso o efeito realça borda sem tocar em área lisa.
    vec3 detail = center.rgb - blurred;
    fragColor = vec4(clamp(center.rgb + detail * amount, 0.0, 1.0), center.a);
}
